_MIX_RESULTS = OrderedDict()
_MIX_LOCK = threading.Lock()
MIX_RESULTS_MAX = 120          # about 120 x 160 kB = 20 MB at most


def _mix_store_key(m, a1, a2, v1, days, seed, party, stamp):
    return (m, ex.mix_key(m, a1, a2, v1), int(days), int(seed), float(party), stamp)


@st.cache_data(show_spinner=False, max_entries=60)
def _run_mixes(a1, a2, v1, days, seed, party, stamp):
    p, burn = fitted()
    keys = {m: _mix_store_key(m, a1, a2, v1, days, seed, party, stamp) for m in ex.MIXES}
    with _MIX_LOCK:
        known = {m: _MIX_RESULTS[k] for m, k in keys.items() if k in _MIX_RESULTS}
    out = ex.run_mixes(p, burn, a1, a2, v1, days, seed, party=party / 100, known=known)
    with _MIX_LOCK:
        for m, k in keys.items():
            if m in out:
                _MIX_RESULTS[k] = out[m]
                _MIX_RESULTS.move_to_end(k)
        while len(_MIX_RESULTS) > MIX_RESULTS_MAX:
            _MIX_RESULTS.popitem(last=False)
    return out


